const pptxgen = require("pptxgenjs");

// ============================================================
// 2024 JavaScript Rising Stars — 8-Slide Deck
// ============================================================

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "2024 JavaScript Rising Stars: Top Projects and Ecosystem Shifts";
pres.author = "JS Rising Stars";

// --------------------------------------------------------
// Design Tokens
// --------------------------------------------------------
const COLORS = {
  navy: "1E2761",
  ice: "CADCFC",
  white: "FFFFFF",
  charcoal: "1E293B",
  slate: "475569",
  muted: "64748B",
  lightBg: "F8FAFC",
  cardBg: "FFFFFF",
  accent: "F59E0B", // amber accent for highlights
  teal: "0D9488",
  tealLight: "14B8A6",
  tealPale: "5EEAD4",
  bar1: "0D9488",
  bar2: "14B8A6",
  bar3: "5EEAD4",
  bar4: "99F6E4",
  bar5: "CCFBF1",
  barMuted: "E2E8F0",
};

const FONTS = {
  header: "Trebuchet MS",
  body: "Calibri",
};

function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// --------------------------------------------------------
// Slide 1: Title Cover
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.navy };

  // Decorative accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: COLORS.teal },
  });

  // Small top label
  slide.addText("9th Edition · Best of JS · GitHub Stars Added in 2024", {
    x: 0.6, y: 1.4, w: 8.5, h: 0.35,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle",
  });

  // Main title
  slide.addText("2024 JavaScript Rising Stars", {
    x: 0.6, y: 1.8, w: 8.5, h: 0.7,
    fontSize: 40, fontFace: FONTS.header, color: COLORS.white,
    bold: true, align: "left", valign: "middle",
  });

  // Subtitle
  slide.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.6, y: 2.55, w: 8.5, h: 0.45,
    fontSize: 22, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle",
  });

  // Bottom stat callouts row
  const stats = [
    { num: "38.0k", label: "shadcn/ui leads" },
    { num: "#1", label: "htmx tops frameworks" },
    { num: "9th", label: "annual edition" },
  ];
  stats.forEach((s, i) => {
    const x = 0.6 + i * 2.8;
    slide.addText(s.num, {
      x, y: 3.6, w: 2.5, h: 0.5,
      fontSize: 28, fontFace: FONTS.header, color: COLORS.tealPale,
      bold: true, align: "left", valign: "middle",
    });
    slide.addText(s.label, {
      x, y: 4.1, w: 2.5, h: 0.3,
      fontSize: 12, fontFace: FONTS.body, color: COLORS.ice,
      align: "left", valign: "middle",
    });
  });

  // Source footer
  slide.addText("Source: risingstars.js.org/2024/en", {
    x: 0.6, y: 5.15, w: 8, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle",
  });
}

// --------------------------------------------------------
// Slide 2: Overall Top 10 (bar chart)
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("shadcn/ui Leads Overall with +38k Stars", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Followed by Excalidraw, AFFiNE, Bruno, and n8n", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  // Horizontal bar chart
  const labels = ["shadcn/ui", "Excalidraw", "AFFiNE", "Bruno", "n8n", "htmx", "Tauri", "Supabase", "Flowise", "Payload"];
  const values = [38.0, 27.0, 19.6, 18.7, 17.0, 16.8, 15.9, 14.5, 14.5, 14.4];

  slide.addChart(pres.charts.BAR, [{
    name: "Stars Added (k)",
    labels,
    values,
  }], {
    x: 0.5, y: 1.3, w: 9, h: 3.8,
    barDir: "bar",
    barGrouping: "clustered",
    chartColors: [COLORS.teal],
    chartArea: { fill: { color: COLORS.lightBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.charcoal,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.charcoal,
    dataLabelFontSize: 10,
    showLegend: false,
    showTitle: false,
    valAxisMaxVal: 42,
    valAxisMinVal: 0,
    catAxisLabelFontSize: 11,
    valAxisLabelFontSize: 10,
  });

  // Footer note
  slide.addText("Data: GitHub stars added during 2024 · Source: Best of JS / Rising Stars", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
  });
}

// --------------------------------------------------------
// Slide 3: shadcn/ui Deep Dive
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("shadcn/ui: Back-to-Back Champion", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Copy-paste components win for the second consecutive year · 77.5k total stars", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  // Left: trend images stacked
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 1.35, w: 4.2, h: 1.7,
    sizing: { type: "contain", w: 4.2, h: 1.7 },
  });
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.5, y: 3.25, w: 4.2, h: 1.7,
    sizing: { type: "contain", w: 4.2, h: 1.7 },
  });

  // Right: feature cards
  const features = [
    "Charts — powered by Recharts",
    "Themes — CSS variable generation",
    "Blocks — layout collections for typical web apps",
    "Responsive Sidebar — new component",
    "Upgraded CLI — Next.js, Remix, Vite, Laravel, monorepos",
    "Registry ecosystem — Motion-Primitives, Magic UI",
    "Vercel v0 integration — AI-generated components",
  ];

  // Card background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 1.35, w: 4.5, h: 3.6,
    fill: { color: COLORS.cardBg },
    shadow: makeShadow(),
  });

  slide.addText("Key 2024 Additions", {
    x: 5.2, y: 1.5, w: 4.1, h: 0.35,
    fontSize: 16, fontFace: FONTS.header, color: COLORS.teal,
    bold: true, align: "left", valign: "middle",
  });

  const bulletItems = features.map((f, idx) => ({
    text: f,
    options: { bullet: true, breakLine: idx < features.length - 1, fontSize: 13, color: COLORS.charcoal },
  }));
  slide.addText(bulletItems, {
    x: 5.2, y: 1.9, w: 4.1, h: 2.9,
    fontFace: FONTS.body,
    valign: "top",
    paraSpaceAfter: 4,
  });

  // Footer
  slide.addText("Source: risingstars.js.org/2024/en", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
  });
}

// --------------------------------------------------------
// Slide 4: Front-end Frameworks (bar chart)
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("htmx Overtakes React as #1 Front-end Framework", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Stars added in 2024 — server-driven, low-JS architectures gain traction", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  // Bar chart
  slide.addChart(pres.charts.BAR, [{
    name: "Stars Added (k)",
    labels: ["htmx", "React", "Svelte", "Vue.js", "Angular"],
    values: [16.8, 14.2, 6.1, 5.9, 3.5],
  }], {
    x: 0.5, y: 1.3, w: 5.5, h: 3.6,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [COLORS.teal],
    chartArea: { fill: { color: COLORS.lightBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.charcoal,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.charcoal,
    dataLabelFontSize: 11,
    showLegend: false,
    showTitle: false,
    valAxisMaxVal: 20,
    valAxisMinVal: 0,
    catAxisLabelFontSize: 12,
    valAxisLabelFontSize: 10,
  });

  // Right-side insight cards
  const insights = [
    { h: "htmx", t: "Extends HTML with hx-* attributes for AJAX & WebSockets — no JS required. Ideal for server-driven apps." },
    { h: "React 19", t: "Server Components, Server Functions, Custom Elements support, new hooks. Evolving from library to framework spec." },
    { h: "Svelte 5", t: "Introduced 'runes' for explicit reactive state. Holds highest positive opinion in State of JS survey." },
  ];

  insights.forEach((ins, i) => {
    const y = 1.3 + i * 1.25;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y, w: 3.2, h: 1.05,
      fill: { color: COLORS.cardBg },
      shadow: makeShadow(),
    });
    slide.addText(ins.h, {
      x: 6.45, y: y + 0.06, w: 2.9, h: 0.28,
      fontSize: 13, fontFace: FONTS.header, color: COLORS.teal,
      bold: true, align: "left", valign: "middle",
    });
    slide.addText(ins.t, {
      x: 6.45, y: y + 0.34, w: 2.9, h: 0.6,
      fontSize: 11, fontFace: FONTS.body, color: COLORS.charcoal,
      align: "left", valign: "top",
    });
  });

  slide.addText("Source: risingstars.js.org/2024/en", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
  });
}

// --------------------------------------------------------
// Slide 5: React Ecosystem
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("React Ecosystem: shadcn/ui, Excalidraw, and Payload Dominate", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Top 5 React ecosystem projects by stars added in 2024", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  const reactProjects = [
    { name: "shadcn/ui", stars: "+38.0k", desc: "Copy-paste components · #1 overall" },
    { name: "Excalidraw", stars: "+27.0k", desc: "Virtual whiteboard for hand-drawn diagrams" },
    { name: "Payload", stars: "+14.4k", desc: "Open-source fullstack Next.js framework" },
    { name: "Magic UI", stars: "+13.2k", desc: "UI registry derivative · animated components" },
    { name: "Next.js", stars: "+12.1k", desc: "React framework · App Router maturation" },
  ];

  reactProjects.forEach((p, i) => {
    const y = 1.35 + i * 0.78;
    // card bg
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 9, h: 0.68,
      fill: { color: COLORS.cardBg },
      shadow: makeShadow(),
    });
    // accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 0.08, h: 0.68,
      fill: { color: COLORS.teal },
    });
    // rank number
    slide.addText(String(i + 1), {
      x: 0.7, y, w: 0.4, h: 0.68,
      fontSize: 18, fontFace: FONTS.header, color: COLORS.teal,
      bold: true, align: "center", valign: "middle",
    });
    // name
    slide.addText(p.name, {
      x: 1.2, y, w: 2.2, h: 0.68,
      fontSize: 15, fontFace: FONTS.header, color: COLORS.charcoal,
      bold: true, align: "left", valign: "middle",
    });
    // stars
    slide.addText(p.stars, {
      x: 3.5, y, w: 1.1, h: 0.68,
      fontSize: 15, fontFace: FONTS.header, color: COLORS.teal,
      bold: true, align: "left", valign: "middle",
    });
    // desc
    slide.addText(p.desc, {
      x: 4.7, y, w: 4.5, h: 0.68,
      fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
      align: "left", valign: "middle",
    });
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: COLORS.navy },
  });
  slide.addText("React is evolving from a library into 'a specification for frameworks' — Robin Wieruch", {
    x: 0.7, y: 5.05, w: 8.6, h: 0.45,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle", italic: true,
  });
}

// --------------------------------------------------------
// Slide 6: Vue Ecosystem
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("Vue Ecosystem Flourishes: Nuxt, PrimeVue, and Slidev Lead Growth", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Top 5 Vue ecosystem projects by stars added in 2024", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  const vueProjects = [
    { name: "Nuxt", stars: "+6.2k", desc: "Fullstack Vue framework · active release cycle" },
    { name: "PrimeVue", stars: "+5.4k", desc: "Rich UI component library for Vue" },
    { name: "Slidev", stars: "+4.7k", desc: "Presentation slides for developers" },
    { name: "shadcn-vue", stars: "+4.1k", desc: "Vue port of shadcn/ui components" },
    { name: "VitePress", stars: "+3.7k", desc: "Static site generator · Vite-powered" },
  ];

  vueProjects.forEach((p, i) => {
    const y = 1.35 + i * 0.78;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 9, h: 0.68,
      fill: { color: COLORS.cardBg },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 0.08, h: 0.68,
      fill: { color: COLORS.teal },
    });
    slide.addText(String(i + 1), {
      x: 0.7, y, w: 0.4, h: 0.68,
      fontSize: 18, fontFace: FONTS.header, color: COLORS.teal,
      bold: true, align: "center", valign: "middle",
    });
    slide.addText(p.name, {
      x: 1.2, y, w: 2.2, h: 0.68,
      fontSize: 15, fontFace: FONTS.header, color: COLORS.charcoal,
      bold: true, align: "left", valign: "middle",
    });
    slide.addText(p.stars, {
      x: 3.5, y, w: 1.1, h: 0.68,
      fontSize: 15, fontFace: FONTS.header, color: COLORS.teal,
      bold: true, align: "left", valign: "middle",
    });
    slide.addText(p.desc, {
      x: 4.7, y, w: 4.5, h: 0.68,
      fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
      align: "left", valign: "middle",
    });
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: COLORS.navy },
  });
  slide.addText("Vue 3.5 reworked reactivity with the lighter alien-signals approach — a maturing ecosystem", {
    x: 0.7, y: 5.05, w: 8.6, h: 0.45,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle", italic: true,
  });
}

// --------------------------------------------------------
// Slide 7: Emerging Themes
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("AI Tools, Desktop Apps, and Browser-Based Innovation Shape 2024", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.charcoal,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Cross-cutting themes from the top projects", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
  });

  const themes = [
    {
      title: "AI Integration",
      stat: "4 of top 10",
      body: "n8n (+17.0k) · Flowise (+14.5k) · Supabase (+14.5k) · AFFiNE (+19.6k). AI is now table stakes for developer tools.",
      color: COLORS.teal,
    },
    {
      title: "Desktop & Mobile",
      stat: "Tauri +15.9k",
      body: "Lighter desktop/mobile apps built with web frontends. Tauri continues to challenge Electron's dominance.",
      color: COLORS.tealLight,
    },
    {
      title: "Browser Innovation",
      stat: "WASM + VM",
      body: "PGlite (Postgres via WebAssembly) and WebVM (full VM in the browser) push the edge of what's possible client-side.",
      color: COLORS.tealPale,
    },
    {
      title: "Backend-as-a-Service",
      stat: "Supabase +14.5k",
      body: "Open-source Firebase alternative gaining strong traction alongside AI-powered workflow tools.",
      color: "0EA5E9",
    },
  ];

  themes.forEach((t, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 0.5 + col * 4.6;
    const y = 1.35 + row * 2.0;

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 4.4, h: 1.75,
      fill: { color: COLORS.cardBg },
      shadow: makeShadow(),
    });

    // Top color strip
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 4.4, h: 0.1,
      fill: { color: t.color },
    });

    slide.addText(t.title, {
      x: x + 0.15, y: y + 0.2, w: 2.6, h: 0.35,
      fontSize: 16, fontFace: FONTS.header, color: COLORS.charcoal,
      bold: true, align: "left", valign: "middle",
    });

    slide.addText(t.stat, {
      x: x + 2.8, y: y + 0.2, w: 1.4, h: 0.35,
      fontSize: 14, fontFace: FONTS.header, color: t.color,
      bold: true, align: "right", valign: "middle",
    });

    slide.addText(t.body, {
      x: x + 0.15, y: y + 0.6, w: 4.1, h: 1.0,
      fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
      align: "left", valign: "top",
    });
  });

  slide.addText("Source: risingstars.js.org/2024/en", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
  });
}

// --------------------------------------------------------
// Slide 8: Key Takeaways
// --------------------------------------------------------
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.navy };

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: COLORS.teal },
  });

  slide.addText("Key Takeaways: What 2024 Tells Us About JavaScript's Future", {
    x: 0.6, y: 0.35, w: 8.8, h: 0.55,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.white,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText("Actionable insights heading into 2025", {
    x: 0.6, y: 0.9, w: 8.8, h: 0.3,
    fontSize: 14, fontFace: FONTS.body, color: COLORS.ice,
    align: "left", valign: "middle",
  });

  const takeaways = [
    { num: "01", text: "Component ownership beats imports", sub: "shadcn/ui's copy-paste model reached 77.5k total stars — developers want control, not black-box dependencies." },
    { num: "02", text: "HTML-first is serious", sub: "htmx overtook React in stars added, validating server-driven, low-JavaScript architectures for production apps." },
    { num: "03", text: "React is becoming a framework spec", sub: "With Server Components and Server Functions in React 19, frameworks (Next.js, Remix) now interpret React differently." },
    { num: "04", text: "AI integration is table stakes", sub: "Four of the top 10 projects embed AI deeply. Expect AI-native features as baseline for new developer tools." },
    { num: "05", text: "Vue's UI library wave signals maturity", sub: "PrimeVue, shadcn-vue, and the Vue 3.5 reactivity overhaul show a confident, growing ecosystem." },
  ];

  takeaways.forEach((t, i) => {
    const y = 1.4 + i * 0.82;

    // Number circle background
    slide.addShape(pres.shapes.OVAL, {
      x: 0.6, y: y + 0.05, w: 0.42, h: 0.42,
      fill: { color: COLORS.teal },
    });
    slide.addText(t.num, {
      x: 0.6, y: y + 0.05, w: 0.42, h: 0.42,
      fontSize: 11, fontFace: FONTS.header, color: COLORS.white,
      bold: true, align: "center", valign: "middle",
    });

    slide.addText(t.text, {
      x: 1.2, y, w: 8.0, h: 0.3,
      fontSize: 15, fontFace: FONTS.header, color: COLORS.tealPale,
      bold: true, align: "left", valign: "middle",
    });

